import type { Locale } from "@/lib/preferences";

import { starName } from "./star-names";

/**
 * Typed, validated, lazy access to the finder chart's star field (every star to magnitude 7.5).
 *
 * `finder-stars.json` is generated by `scripts/build-stars.mjs` from the HYG database v4.1 (CC BY-SA 4.0, itself
 * compiled from ESA's Hipparcos, CC BY-NC 3.0 IGO) and must not be edited by hand. It is columnar integers
 * (`pos`: right ascension and declination in 0.01 degrees packed into one integer; `mag`: runs of [tenths, count]) with a sparse table
 * of designation tuples; HYG ids order the stars but are not stored, to keep the gzip under the size budget.
 *
 * Server-only: it is ~25,800 stars, parsed only when the finder route asks, through a dynamic `import()` so the
 * Worker does not parse it for any other page. Never import it from `stars.ts`, `./index` or any island (a React
 * component, `src/lib/sky-view/**`); `finder-stars.test.ts` scans for that.
 */

/** How HYG names a star besides its HYG id: Bayer letter, Flamsteed number, constellation and proper name. */
export interface StarDesignation {
  /** HYG's three-letter Greek abbreviation, with a `-<n>` suffix for a component ("Alp", "Pi-1") */
  bayer?: string;
  flamsteed?: number;
  /** IAU constellation abbreviation ("And") */
  con: string;
  /** English proper name ("Mirach") */
  proper?: string;
}

export interface FinderStar {
  /** Position in the file's columns: brightest first, ties by HYG id (not stored) */
  index: number;
  /** Apparent visual magnitude, in steps of 0.1 */
  mag: number;
  /** J2000 equatorial unit vector: x towards the March equinox, z towards the north celestial pole */
  vector: readonly [number, number, number];
  /** Null for the ~87 % of stars with no Bayer letter, Flamsteed number or proper name */
  designation: StarDesignation | null;
}

/** 25,791 at the pinned HYG commit; the range matches the generator's margin. */
export const FINDER_STAR_COUNT_RANGE = { min: 25741, max: 25841 } as const;
export const FINDER_STAR_MAX_MAG = 7.5;

const RA_UNITS_PER_TURN = 36000;
const DEC_UNITS_MAX = 9000;
/** `pos` = raCenti * POS_DEC_RANGE + (decCenti + DEC_UNITS_MAX), raCenti 0..35999, decCenti -9000..9000 */
const POS_DEC_RANGE = 2 * DEC_UNITS_MAX + 1;
const POS_MAX = RA_UNITS_PER_TURN * POS_DEC_RANGE - 1;
/** Sirius, -1.44, is the brightest star in the file. */
const MIN_MAG_TENTHS = -15;
const MAX_MAG_TENTHS = FINDER_STAR_MAX_MAG * 10;

function fail(message: string): never {
  throw new Error(`finder-stars.json: ${message}`);
}

function requireIntegerColumn(raw: Record<string, unknown>, key: string, min: number, max: number): readonly number[] {
  const column = raw[key];
  if (!Array.isArray(column)) {
    fail(`${key} is not an array`);
  }
  const { min: minCount, max: maxCount } = FINDER_STAR_COUNT_RANGE;
  if (column.length < minCount || column.length > maxCount) {
    fail(`${key} has ${column.length} entries, expected ${minCount}..${maxCount}`);
  }
  column.forEach((value: unknown, index) => {
    if (typeof value !== "number" || !Number.isInteger(value) || value < min || value > max) {
      fail(`${key}[${index}] must be an integer in [${min}, ${max}]`);
    }
  });
  return column as readonly number[];
}

/** A designations entry: [bayer, flamsteed, con, proper], null for an absent field. */
function validateDesignation(value: unknown, key: string): StarDesignation {
  if (!Array.isArray(value) || value.length !== 4) {
    fail(`designations[${key}] is not a [bayer, flamsteed, con, proper] tuple`);
  }
  const [bayer, flamsteed, con, proper] = value as unknown[];
  if (typeof con !== "string" || con.length === 0) {
    fail(`designations[${key}] con must be a non-empty string`);
  }
  const designation: StarDesignation = { con };
  if (bayer !== null) {
    if (typeof bayer !== "string" || bayer.length === 0) {
      fail(`designations[${key}] bayer must be null or a non-empty string`);
    }
    designation.bayer = bayer;
  }
  if (flamsteed !== null) {
    if (typeof flamsteed !== "number" || !Number.isInteger(flamsteed) || flamsteed <= 0) {
      fail(`designations[${key}] flamsteed must be null or a positive integer`);
    }
    designation.flamsteed = flamsteed;
  }
  if (proper !== null) {
    if (typeof proper !== "string" || proper.length === 0) {
      fail(`designations[${key}] proper must be null or a non-empty string`);
    }
    designation.proper = proper;
  }
  if (bayer === null && flamsteed === null && proper === null) {
    fail(`designations[${key}] carries no name`);
  }
  return designation;
}

/**
 * Decodes the `mag` runs, [tenths, count] over the sorted stars, into one magnitude in tenths per star. The runs must
 * not decrease, stay within [-15, 75] and add up to `total`.
 */
export function unpackMagnitudes(runs: unknown, total: number): readonly number[] {
  if (!Array.isArray(runs)) {
    fail("mag is not an array");
  }
  const tenths: number[] = [];
  let previous = Number.NEGATIVE_INFINITY;
  runs.forEach((run: unknown, index) => {
    if (!Array.isArray(run) || run.length !== 2) {
      fail(`mag[${index}] is not a [tenths, count] run`);
    }
    const [value, count] = run as unknown[];
    if (typeof value !== "number" || !Number.isInteger(value) || value < MIN_MAG_TENTHS || value > MAX_MAG_TENTHS) {
      fail(`mag[${index}] tenths must be an integer in [${MIN_MAG_TENTHS}, ${MAX_MAG_TENTHS}]`);
    }
    if (value < previous) {
      fail(`mag[${index}] runs back to ${value} after ${previous}: the stars are not sorted by magnitude`);
    }
    if (typeof count !== "number" || !Number.isInteger(count) || count < 1 || tenths.length + count > total) {
      fail(`mag[${index}] count must be a positive integer within the star count`);
    }
    for (let n = 0; n < count; n++) {
      tenths.push(value);
    }
    previous = value;
  });
  if (tenths.length !== total) {
    fail(`mag runs cover ${tenths.length} stars, expected ${total}`);
  }
  return tenths;
}

/** Decodes a `pos` value into right ascension and declination in 0.01 degrees, throwing when either is out of range. */
export function unpackPosition(packed: number): { raCenti: number; decCenti: number } {
  const raCenti = Math.floor(packed / POS_DEC_RANGE);
  const decCenti = (packed % POS_DEC_RANGE) - DEC_UNITS_MAX;
  if (!Number.isInteger(packed) || raCenti < 0 || raCenti >= RA_UNITS_PER_TURN || Math.abs(decCenti) > DEC_UNITS_MAX) {
    fail(`pos ${packed} does not decode to a right ascension in [0, ${RA_UNITS_PER_TURN}) and a declination in range`);
  }
  return { raCenti, decCenti };
}

function validateStars(input: unknown): readonly FinderStar[] {
  if (typeof input !== "object" || input === null || Array.isArray(input)) {
    fail("not an object");
  }
  const raw = input as Record<string, unknown>;
  const pos = requireIntegerColumn(raw, "pos", 0, POS_MAX);
  const mag = unpackMagnitudes(raw.mag, pos.length);
  const table = raw.designations;
  if (typeof table !== "object" || table === null || Array.isArray(table)) {
    fail("designations is not an object");
  }
  const designations = new Map<number, StarDesignation>();
  for (const [key, value] of Object.entries(table)) {
    const index = Number(key);
    if (!Number.isInteger(index) || index < 0 || index >= pos.length) {
      fail(`designations key "${key}" is not a star index`);
    }
    designations.set(index, validateDesignation(value, key));
  }

  return pos.map((packed, index) => {
    const { raCenti, decCenti } = unpackPosition(packed);
    const raRad = (raCenti / 100) * (Math.PI / 180);
    const decRad = (decCenti / 100) * (Math.PI / 180);
    return {
      index,
      mag: mag[index] / 10,
      vector: [Math.cos(decRad) * Math.cos(raRad), Math.cos(decRad) * Math.sin(raRad), Math.sin(decRad)] as const,
      designation: designations.get(index) ?? null,
    };
  });
}

let loading: Promise<readonly FinderStar[]> | undefined;

/**
 * The finder star field, validated once per isolate. A failed load (a malformed regeneration, a chunk that did not
 * arrive) is not memoised, so a later call tries again.
 */
export function loadFinderStars(): Promise<readonly FinderStar[]> {
  loading ??= import("./finder-stars.json").then((module) => validateStars(module.default as unknown));
  const current = loading;
  current.catch(() => {
    if (loading === current) {
      loading = undefined;
    }
  });
  return current;
}

const GREEK: Readonly<Record<string, string>> = {
  Alp: "α",
  Bet: "β",
  Gam: "γ",
  Del: "δ",
  Eps: "ε",
  Zet: "ζ",
  Eta: "η",
  The: "θ",
  Iot: "ι",
  Kap: "κ",
  Lam: "λ",
  Mu: "μ",
  Nu: "ν",
  Xi: "ξ",
  Omi: "ο",
  Pi: "π",
  Rho: "ρ",
  Sig: "σ",
  Tau: "τ",
  Ups: "υ",
  Phi: "φ",
  Chi: "χ",
  Psi: "ψ",
  Ome: "ω",
};

const SUPERSCRIPT_DIGITS = "⁰¹²³⁴⁵⁶⁷⁸⁹";

/** "Pi-1" -> "π¹"; an abbreviation HYG uses that this table lacks stays as HYG wrote it. */
function bayerLetter(bayer: string): string {
  const [abbreviation, component = ""] = bayer.split("-");
  const letter = GREEK[abbreviation] ?? abbreviation;
  return letter + component.replace(/\d/g, (digit) => SUPERSCRIPT_DIGITS.charAt(Number(digit)));
}

/**
 * The label for a star on the chart: "β And" (Bayer), "43 And" (Flamsteed only), and with a proper name
 * "Mirach (β And)" (the name in `locale`, through `starName`); a named star with neither letter nor number is just
 * its name. Null when the star has no designation.
 */
export function formatDesignation(designation: StarDesignation | null, locale: Locale): string | null {
  if (designation === null) {
    return null;
  }
  let label: string | null = null;
  if (designation.bayer !== undefined) {
    label = `${bayerLetter(designation.bayer)} ${designation.con}`;
  } else if (designation.flamsteed !== undefined) {
    label = `${designation.flamsteed} ${designation.con}`;
  }
  if (designation.proper === undefined) {
    return label;
  }
  const name = starName(designation.proper, locale);
  return label === null ? name : `${name} (${label})`;
}
